import { Box, FillPreview, IconButton, Input, NumberInput, Slider } from '@wix/design-system';
import { DeleteSmall } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useMemo, useState } from 'react';

import { RicosContext } from './../../../../../ricos-context/index.js';
import type { Gradient, GradientStop } from './../../../../../ricos-types/color-palette-types.js';
import { resolveColorToDisplayHex } from './../../../../../_shared/resolve-color-to-display-hex.js';
import {
  combineHexWithOpacity,
  getHexColorFromAlpha,
  getOpacityFromHex,
} from './../../../../../wix-rich-content-common/index.js';
import { usePanelContainerElement } from './../../../../ui-components-provider.js';

export type OpenGradientStopColorPicker = (props: {
  originalIndex: number;
  stop: GradientStop;
  referenceElement: HTMLElement | undefined | null;
}) => void;

type GradientStopEditorProps = {
  value: Gradient;
  stop: GradientStop & { originalIndex: number };
  onChange: (gradient: Gradient) => void;
  originalIndex: number;
  onColorPickerOpen?: OpenGradientStopColorPicker;
};

export const GradientStopEditor: FC<GradientStopEditorProps> = ({
  value,
  stop,
  onChange,
  originalIndex,
  onColorPickerOpen,
}) => {
  const { t } = useContext(RicosContext);
  const panelContainerEl = usePanelContainerElement();
  const [containerElement, setContainerElement] = useState<HTMLDivElement | null>(null);
  const colorResolverElement = panelContainerEl ?? containerElement;
  const displayColor = useMemo(
    () => resolveColorToDisplayHex(stop.color, colorResolverElement),
    [stop.color, colorResolverElement]
  );
  const previewColor = useMemo(
    () => resolveColorToDisplayHex(stop.color, colorResolverElement, { preserveAlpha: true }),
    [stop.color, colorResolverElement]
  );
  const stopOpacity = getOpacityFromHex(stop.color);

  return (
    <Box key={originalIndex} direction="horizontal" gap="SP2" ref={setContainerElement}>
      <Box width="100%" marginRight="SP2">
        <Slider
          displayMarks={false}
          gradientColor={displayColor}
          min={0}
          max={100}
          value={stopOpacity}
          onChange={newOpacity => {
            const opacityValue = Array.isArray(newOpacity) ? newOpacity[0] : newOpacity;
            onChange({
              ...value,
              stops: value.stops?.map((s, i) =>
                i === originalIndex
                  ? {
                      ...s,
                      color: combineHexWithOpacity(getHexColorFromAlpha(s.color), opacityValue),
                    }
                  : s
              ),
            });
          }}
        />
      </Box>
      <Box flexShrink="0" width="70px">
        <NumberInput
          value={stopOpacity}
          suffix={<Input.Affix>%</Input.Affix>}
          size="small"
          min={0}
          max={100}
          hideStepper
          onChange={newOpacity => {
            const opacityValue = Math.max(0, Math.min(100, Number(newOpacity)));
            onChange({
              ...value,
              stops: value.stops?.map((s, i) =>
                i === originalIndex
                  ? {
                      ...s,
                      color: combineHexWithOpacity(getHexColorFromAlpha(s.color), opacityValue),
                    }
                  : s
              ),
            });
          }}
        />
      </Box>
      <Box flexShrink="0">
        <FillPreview
          dataHook={`gradient-fill-preview-${originalIndex}`}
          size="small"
          onClick={() => {
            onColorPickerOpen?.({
              originalIndex,
              stop,
              referenceElement: containerElement,
            });
          }}
          fill={previewColor}
        />
      </Box>
      <Box flexShrink="0">
        <IconButton
          ariaLabel={t('GradientPicker_RemoveStop_Tooltip')}
          disabled={value.stops?.length === 1}
          priority="secondary"
          size="small"
          onClick={() => {
            onChange({
              ...value,
              stops: value.stops?.filter((_, i) => i !== originalIndex),
            });
          }}
        >
          <DeleteSmall />
        </IconButton>
      </Box>
    </Box>
  );
};
