import type {
  RicosAssetState,
  RicosInvocationEffects,
  RicosInvocationState,
} from '../../../../../ricos-window';

type AssistantWidgetStatus = Parameters<
  NonNullable<RicosAssetState<unknown>['updateAssistantWidgetStatus']>
>[0];

export const INVOCATION_UPDATE_EVENT = 'ricos-assistant-invocation-update';

const getStores = () => {
  if (typeof window === 'undefined') {
    return undefined;
  }

  window.RICOS ??= {};
  window.RICOS_INVOCATIONS ??= {};

  return {
    assets: window.RICOS,
    invocations: window.RICOS_INVOCATIONS,
  };
};

export const getAssetState = <TEditorRef = unknown, TWorkspaceContext = unknown>(
  assetId: string
): RicosAssetState<TEditorRef, TWorkspaceContext> | undefined => {
  return getStores()?.assets[assetId] as RicosAssetState<TEditorRef, TWorkspaceContext> | undefined;
};

export const getAssetEditorRef = <TEditorRef = unknown>(assetId: string) =>
  getAssetState<TEditorRef>(assetId)?.editorRef;

export const setAssetWaitingState = (assetId: string) => {
  const stores = getStores();
  if (!stores) {
    return;
  }

  const asset = stores.assets[assetId] ?? (stores.assets[assetId] = {});
  asset.isLoadingFromWidget = true;
  asset.setIsWaitingForStream?.(true);
};

export const clearAssetWaitingState = (assetId: string) => {
  const asset = getAssetState(assetId);
  if (asset) {
    asset.setIsWaitingForStream?.(false);
    asset.isLoadingFromWidget = false;
  }
};

export const setAssetWidgetStatus = (assetId: string, status: AssistantWidgetStatus) =>
  getAssetState(assetId)?.updateAssistantWidgetStatus?.(status);

export const getInvocation = (invocationId: string): RicosInvocationState | undefined => {
  return getStores()?.invocations[invocationId];
};

export const setInvocation = (invocationId: string, state: RicosInvocationState) => {
  const stores = getStores();
  if (!stores) {
    return state;
  }

  stores.invocations[invocationId] = state;
  window.dispatchEvent(
    new CustomEvent(INVOCATION_UPDATE_EVENT, {
      detail: { invocationId, state },
    })
  );
  return state;
};

const updateStoredInvocation = (
  invocationId: string,
  updater: (current: RicosInvocationState) => RicosInvocationState
) => {
  const current = getInvocation(invocationId);
  if (!current) {
    return undefined;
  }

  const next = updater(current);
  if (next === current) {
    return current;
  }

  return setInvocation(invocationId, next);
};

export const hasInvocationEffect = (invocationId: string, effect: keyof RicosInvocationEffects) =>
  Boolean(getInvocation(invocationId)?.effects?.[effect]);

export const setInvocationEffect = (invocationId: string, effect: keyof RicosInvocationEffects) =>
  updateStoredInvocation(invocationId, current => {
    if (current.effects?.[effect]) {
      return current;
    }

    return {
      ...current,
      effects: {
        ...current.effects,
        [effect]: true,
      },
    };
  });

export const subscribeToInvocation = (
  invocationId: string,
  listener: (state: RicosInvocationState | undefined) => void
) => {
  if (typeof window === 'undefined') {
    return () => {};
  }

  const handleUpdate = (event: Event) => {
    const detail = (
      event as CustomEvent<{
        invocationId: string;
        state?: RicosInvocationState;
      }>
    ).detail;

    if (detail?.invocationId === invocationId) {
      listener(detail.state);
    }
  };

  window.addEventListener(INVOCATION_UPDATE_EVENT, handleUpdate);
  return () => {
    window.removeEventListener(INVOCATION_UPDATE_EVENT, handleUpdate);
  };
};
