import { Box, FieldSet, FormField, ToggleButton } from '@wix/design-system';
import { CircleSmallFilledSmall } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import { POSITION_TOGGLE_BUTTON } from './data-hooks.js';

export type Position =
  | 'TOP'
  | 'TOP_LEFT'
  | 'TOP_RIGHT'
  | 'CENTER'
  | 'CENTER_LEFT'
  | 'CENTER_RIGHT'
  | 'BOTTOM'
  | 'BOTTOM_LEFT'
  | 'BOTTOM_RIGHT';

type PositionSelectorProps = {
  label: string;
  value: Position;
  onChange: (value: Position) => void;
  dataHook?: string;
};

export const PositionSelectorWithLabel: React.FC<PositionSelectorProps> = ({
  label,
  value,
  onChange,
  dataHook,
}) => {
  return (
    <Box direction="vertical" dataHook={dataHook}>
      <FormField inputWidth="100%">
        <FieldSet columns="auto 84px" alignment="center" legend={label} legendPlacement="left">
          <div />
          <PositionGrid value={value} onChange={onChange} />
        </FieldSet>
      </FormField>
    </Box>
  );
};
type PositionGridProps = {
  value: Position;
  onChange: (value: Position) => void;
};

const PositionGrid: React.FC<PositionGridProps> = ({ value, onChange }) => {
  return (
    <Box direction="vertical" gap="SP1">
      <Box direction="horizontal" gap="SP1">
        <PositionToggle currentSelection={value} value="TOP_LEFT" onClick={onChange} />
        <PositionToggle currentSelection={value} value="TOP" onClick={onChange} />
        <PositionToggle currentSelection={value} value="TOP_RIGHT" onClick={onChange} />
      </Box>

      <Box direction="horizontal" gap="SP1">
        <PositionToggle currentSelection={value} value="CENTER_LEFT" onClick={onChange} />
        <PositionToggle currentSelection={value} value="CENTER" onClick={onChange} />
        <PositionToggle currentSelection={value} value="CENTER_RIGHT" onClick={onChange} />
      </Box>

      <Box direction="horizontal" gap="SP1">
        <PositionToggle currentSelection={value} value="BOTTOM_LEFT" onClick={onChange} />
        <PositionToggle currentSelection={value} value="BOTTOM" onClick={onChange} />
        <PositionToggle currentSelection={value} value="BOTTOM_RIGHT" onClick={onChange} />
      </Box>
    </Box>
  );
};

type PositionToggleProps = {
  onClick: (value: Position) => void;
  value: Position;
  currentSelection: Position;
};

const PositionToggle: React.FC<PositionToggleProps> = ({ onClick, value, currentSelection }) => {
  return (
    <ToggleButton
      skin="inverted"
      selected={currentSelection === value}
      size="tiny"
      onClick={() => onClick(value)}
      tooltipProps={{ disabled: true }}
      border
      dataHook={`${POSITION_TOGGLE_BUTTON}-${value}`}
    >
      {currentSelection === value ? <CircleSmallFilledSmall /> : <Box />}
    </ToggleButton>
  );
};
