import { Button } from '@wix/design-system';
import { StopFilledSmall } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import type { RicosInvocationState } from '../../../../../ricos-window';
import type { AiMessage, AiMessageText } from '../../plugin-inline-ai/types.js';
import type { RicosEditorAPI } from '../../ricos-types/editor-types.js';
import { getAssistantErrorDescriptor } from './assistant-error-descriptor.js';
import type { CodegenTask } from './assistant-timeline.js';
import { MessageTimeline } from './assistant-timeline.js';
import {
  clearAssetWaitingState,
  getAssetEditorRef,
  getInvocation,
  hasInvocationEffect,
  setInvocationEffect,
  subscribeToInvocation,
  setAssetWidgetStatus,
} from './runtime-store.js';

export type RicosWidgetProps = {
  data: {
    messageId: string;
    assetId?: string;
    prompt: string;
    assetNameSuggestion?: string;
  };
  config: {
    messageIndex?: number;
    messages?: unknown[];
    setCanSend?: (canSend: boolean) => void;
  };
  context: {
    send?: (message: string) => void;
  };
  platform: {
    openPaywallModal: () => void;
    t: (key: string) => string;
    endAiGeneration: (context: { generationId: string; assetId: string }) => void;
    retryInvocation: (invocationId: string) => Promise<string>;
  };
};

type WidgetData = RicosWidgetProps['data'];
type WidgetConfig = RicosWidgetProps['config'];
type WidgetContext = RicosWidgetProps['context'];
type PlatformAPI = RicosWidgetProps['platform'];

/*
Widget state handoff

  tool / stage starts AI imperatively
    -> invocation manager updates window.RICOS_INVOCATIONS
    -> widget mounts and reads startup state by invocationId
    -> widget shows pending/startupFailed while editor runtime is not ready
    -> once editorRef.useInlineAiState(invocationId) exists,
       runtime state becomes the source of truth

  In short:
    bridge state owns startup
    editor inline AI state owns execution
    widget only renders and reacts
*/

const logError = (message: string, error: unknown, details?: Record<string, unknown>) => {
  console.error('[ricos-assistant-widget]', message, {
    ...details,
    error,
  });
};

type StopButtonProps = {
  onCancel: () => void;
  t: (key: string) => string;
};

const StopButton: React.FC<StopButtonProps> = ({ onCancel, t }) => {
  return (
    <Button
      size="small"
      priority="secondary"
      skin="standard"
      prefixIcon={<StopFilledSmall />}
      onClick={onCancel}
    >
      {t('Widget_Button_Stop')}
    </Button>
  );
};

const useInvocationState = (invocationId: string) => {
  const [state, setState] = React.useState<RicosInvocationState | undefined>(() =>
    getInvocation(invocationId)
  );

  React.useEffect(() => {
    setState(getInvocation(invocationId));
    return subscribeToInvocation(invocationId, setState);
  }, [invocationId]);

  return state;
};

const getStartupTasks = (
  invocationState: RicosInvocationState | undefined,
  t: (key: string) => string
): CodegenTask[] => {
  if (invocationState?.assetMode !== 'create') {
    return [];
  }

  const status =
    invocationState.phase === 'creatingAsset'
      ? 'inProgress'
      : invocationState.phase === 'startupFailed' && !('assetId' in invocationState)
        ? 'error'
        : 'success';

  return [
    {
      message: t('Widget_Message_CreatingAsset'),
      status,
    },
  ];
};

type InlineAiState = ReturnType<RicosEditorAPI['useInlineAiState']>;
const useRuntimeEffects = (
  aiState: InlineAiState,
  assetId: string,
  generationId: string | undefined,
  invocationId: string,
  isLastMessage: boolean,
  isRetry: boolean,
  hasContentStarted: boolean,
  platform: PlatformAPI,
  config: WidgetConfig,
  context: WidgetContext
) => {
  const currentState = aiState?.state;
  const runtimeStateType = currentState?.type;

  const endGenerationIfNeeded = React.useCallback(() => {
    if (!generationId || hasInvocationEffect(invocationId, 'generationEnded')) {
      return;
    }

    setInvocationEffect(invocationId, 'generationEnded');
    platform.endAiGeneration({ generationId, assetId });
  }, [assetId, generationId, invocationId, platform]);

  const releaseLoader = React.useCallback(() => {
    if (!hasInvocationEffect(invocationId, 'loaderReleased')) {
      setInvocationEffect(invocationId, 'loaderReleased');
      clearAssetWaitingState(assetId);
    }
    endGenerationIfNeeded();
  }, [assetId, endGenerationIfNeeded, invocationId]);

  React.useEffect(() => {
    if (!(isLastMessage || isRetry)) {
      return;
    }

    if (currentState?.type && currentState.type !== 'typing') {
      setAssetWidgetStatus(assetId, currentState.type);
    }

    switch (currentState?.type) {
      case 'pending':
        config.setCanSend?.(false);
        break;
      case 'streaming':
        if (hasContentStarted) {
          releaseLoader();
        } else {
          endGenerationIfNeeded();
        }
        break;
      case 'closed': {
        config.setCanSend?.(true);

        if (hasInvocationEffect(invocationId, 'terminalMessageSent')) {
          break;
        }

        setInvocationEffect(invocationId, 'terminalMessageSent');
        releaseLoader();

        const summary = currentState.messages.find(
          (message: AiMessage): message is AiMessageText =>
            message.type === 'text' && message.subtype === 'summary'
        );
        const explanation = currentState.messages.find(
          (message: AiMessage): message is AiMessageText =>
            message.type === 'text' && message.subtype === 'explain'
        );

        if (summary) {
          context.send?.(`<HIDDEN>Summary of performed changes: ${summary.text}</HIDDEN>`);
        } else if (explanation) {
          context.send?.(`<HIDDEN>No changes performed. Explanation: ${explanation.text}</HIDDEN>`);
        } else {
          context.send?.('<HIDDEN>Request completed</HIDDEN>');
        }
        break;
      }
      case 'error': {
        config.setCanSend?.(true);

        if (hasInvocationEffect(invocationId, 'terminalMessageSent')) {
          break;
        }

        setInvocationEffect(invocationId, 'terminalMessageSent');
        releaseLoader();

        const errorDescriptor = getAssistantErrorDescriptor({
          applicationErrorCode: currentState.error.applicationErrorCode,
          message: currentState.error.message,
          t: platform.t,
        });

        if (errorDescriptor.shouldOpenPaywall) {
          platform.openPaywallModal();
        }

        context.send?.(errorDescriptor.hiddenMessage);
        break;
      }
      default:
        break;
    }
  }, [
    assetId,
    config,
    context,
    endGenerationIfNeeded,
    hasContentStarted,
    invocationId,
    isLastMessage,
    isRetry,
    platform,
    releaseLoader,
    runtimeStateType,
  ]);
};

export const RicosWidget: React.FC<RicosWidgetProps> = ({ platform, ...props }) => {
  const [currentInvocationId, setCurrentInvocationId] = React.useState(props.data.messageId);
  const invocationState = useInvocationState(currentInvocationId);

  const { t } = platform;
  const initialTasks = getStartupTasks(invocationState, t);
  const assetId =
    (invocationState && 'assetId' in invocationState ? invocationState.assetId : undefined) ??
    props.data.assetId;
  const editorRef = assetId ? getAssetEditorRef<RicosEditorAPI>(assetId) : undefined;
  const hideWidget = !invocationState;
  const isStartupFailed = invocationState?.phase === 'startupFailed';
  const isPending =
    !hideWidget &&
    !isStartupFailed &&
    (!invocationState ||
      invocationState.phase === 'initializing' ||
      invocationState.phase === 'waitingForEditor' ||
      !editorRef ||
      !assetId);

  React.useEffect(() => {
    setCurrentInvocationId(props.data.messageId);
  }, [props.data.messageId]);

  const handleRetry = React.useCallback(() => {
    void platform
      .retryInvocation(currentInvocationId)
      .then(newInvocationId => {
        setCurrentInvocationId(newInvocationId);
      })
      .catch(error => {
        logError('retry failed', error, {
          currentInvocationId,
          assetId,
        });
      });
  }, [assetId, currentInvocationId, platform]);

  if (hideWidget) {
    return null;
  }

  if (isStartupFailed) {
    const errorMessage = invocationState?.error?.message;
    return (
      <div data-hook="ricos-widget" data-state="error">
        <MessageTimeline
          title={t('Widget_Title_Error')}
          subtitle={t('Widget_Subtitle_Error')}
          tasks={[
            ...initialTasks,
            {
              message: errorMessage ?? t('Widget_Subtitle_Error'),
              status: 'error',
              description: errorMessage ? [errorMessage] : undefined,
            },
          ]}
          onRetry={handleRetry}
          t={t}
        />
      </div>
    );
  }

  if (isPending || !assetId || !editorRef) {
    return (
      <div data-hook="ricos-widget" data-state="pending">
        <MessageTimeline
          title={t('Widget_Title_Pending')}
          subtitle={t('Widget_Subtitle_Pending')}
          tasks={initialTasks}
          isLoading={initialTasks.length === 0}
          t={t}
        />
      </div>
    );
  }

  return (
    <RicosWidgetSession
      {...props}
      platform={platform}
      data={{ ...props.data, assetId }}
      generationId={
        invocationState && 'generationId' in invocationState
          ? invocationState.generationId
          : undefined
      }
      initialTasks={initialTasks}
      invocationId={currentInvocationId}
      isRetry={currentInvocationId !== props.data.messageId}
      onRetry={handleRetry}
      editorRef={editorRef}
    />
  );
};

type RicosWidgetSessionProps = {
  data: WidgetData & { assetId: string };
  config: WidgetConfig;
  context: WidgetContext;
  platform: PlatformAPI;
  initialTasks?: CodegenTask[];
  generationId?: string;
  invocationId: string;
  isRetry: boolean;
  onRetry: () => void;
  editorRef: RicosEditorAPI;
};

const TOOL_LABELS: Record<string, string> = {
  web_search: 'Researching',
  web_scrape: 'Reading web page',
  image_search: 'Looking for images',
  image_generation: 'Generating image',
  analyze_resource: 'Analyzing',
  read_wix_blog_post: 'Reading blog post',
  read_wix_event: 'Reading event',
  read_wix_stores_product: 'Reading product',
  read_wix_booking_service: 'Reading booking service',
  generate_theme: 'Generating theme',
};

const isRecord = (value: unknown): value is Record<string, unknown> => {
  return typeof value === 'object' && value !== null;
};

const getToolDescription = (m: AiMessageText): string => {
  const toolName = m.text.toLowerCase();
  const label = TOOL_LABELS[toolName] || m.text;
  const params = isRecord(m.toolParameters) ? m.toolParameters : undefined;
  if (!params) {
    return label;
  }

  const getRequestValues = (key: 'query' | 'prompt') =>
    Array.isArray(params.requests)
      ? params.requests.reduce<string[]>((values, request) => {
          if (isRecord(request) && typeof request[key] === 'string') {
            values.push(request[key]);
          }
          return values;
        }, [])
      : [];

  let summary: string | undefined;
  switch (toolName) {
    case 'web_search':
      summary = getRequestValues('query').join(', ') || undefined;
      break;
    case 'image_search':
      summary = typeof params.searchTerm === 'string' ? params.searchTerm : undefined;
      break;
    case 'image_generation':
      summary = typeof params.prompt === 'string' ? params.prompt : undefined;
      break;
    case 'web_scrape':
      summary = typeof params.url === 'string' ? params.url : undefined;
      break;
    case 'analyze_resource':
      summary = getRequestValues('prompt').join(', ') || undefined;
      break;
  }
  return summary ? `${label}: ${summary}` : label;
};

const buildResearchingTask = (
  textMessages: AiMessageText[],
  status: CodegenTask['status'],
  t: (key: string) => string
): CodegenTask | null => {
  const descriptions = textMessages.filter(m => m.subtype === 'tool').map(getToolDescription);
  if (descriptions.length === 0) {
    return null;
  }
  return {
    id: 'researching',
    message: t('Widget_Timeline_Step_GatheringInformation'),
    description: descriptions,
    isToolDescription: status === 'inProgress',
    status,
  };
};

const RicosWidgetSession: React.FC<RicosWidgetSessionProps> = ({
  platform,
  initialTasks = [],
  generationId,
  invocationId,
  isRetry,
  editorRef,
  ...props
}) => {
  const { t } = platform;
  const assetId = props.data.assetId;
  const isLastMessage = props.config.messageIndex === (props.config.messages?.length ?? 0) - 1;
  const aiState = editorRef.useInlineAiState(invocationId);
  const runtimeMessages =
    aiState?.state && 'messages' in aiState.state ? aiState.state.messages : [];
  const hasContentStarted =
    aiState?.state?.type === 'streaming' &&
    runtimeMessages.some((m: AiMessage) => m.type === 'insert' || m.type === 'replace');

  useRuntimeEffects(
    aiState,
    assetId,
    generationId,
    invocationId,
    isLastMessage,
    isRetry,
    hasContentStarted,
    platform,
    props.config,
    props.context
  );

  if (!aiState?.state) {
    return (
      <div data-hook="ricos-widget" data-state="pending">
        <MessageTimeline
          title={t('Widget_Title_Pending')}
          subtitle={t('Widget_Subtitle_Pending')}
          tasks={initialTasks}
          isLoading={initialTasks.length === 0}
          t={t}
        />
      </div>
    );
  }

  const textMessages =
    'messages' in aiState.state
      ? aiState.state.messages.filter((m): m is AiMessageText => m.type === 'text')
      : [];
  const summaryMessage =
    textMessages.find(m => m.subtype === 'summary') ??
    textMessages.find(m => m.subtype === 'explain') ??
    textMessages.find(m => m.subtype === 'error');

  const baseTasks: CodegenTask[] = [
    {
      message: t('Widget_Timeline_Step_Executing'),
      description: [props.data.prompt],
      status: 'pending',
    },
    {
      message: t('Widget_Timeline_Step_GeneratingResponse'),
      status: 'pending',
    },
    {
      message: t('Widget_Timeline_Step_Summary'),
      status: 'pending',
    },
  ];

  const onCancel = () => aiState.stop({ headless: true });

  switch (aiState.state.type) {
    case 'pending': {
      const tasksWithStatus: CodegenTask[] = [{ ...baseTasks[0], status: 'inProgress' }];
      return (
        <div data-hook="ricos-widget" data-state="pending">
          <MessageTimeline
            title={t('Widget_Title_Editing')}
            subtitle={t('Widget_Subtitle_ExecutingPrompt')}
            tasks={[...initialTasks, ...tasksWithStatus]}
            footer={
              <div data-hook="ricos-widget-stop-button">
                <StopButton onCancel={onCancel} t={t} />
              </div>
            }
            t={t}
          />
        </div>
      );
    }
    case 'streaming': {
      const researchingTask = hasContentStarted
        ? buildResearchingTask(textMessages, 'success', t)
        : buildResearchingTask(textMessages, 'inProgress', t);
      const tasksWithStatus: CodegenTask[] = hasContentStarted
        ? [
            {
              ...baseTasks[0],
              status: 'success',
            },
            ...(researchingTask ? [researchingTask] : []),
            {
              ...baseTasks[1],
              status: !summaryMessage
                ? 'inProgress'
                : summaryMessage.subtype === 'error'
                  ? 'error'
                  : 'success',
              applicationErrorCode:
                summaryMessage?.subtype === 'error' ? 'AI_GENERATED_ERROR' : undefined,
              description: summaryMessage?.subtype === 'error' ? [summaryMessage.text] : undefined,
            },
            ...(summaryMessage
              ? [
                  {
                    ...baseTasks[2],
                    status: 'inProgress' as const,
                    description: summaryMessage.text ? [summaryMessage.text] : undefined,
                  },
                ]
              : []),
          ]
        : [
            {
              ...baseTasks[0],
              status: researchingTask ? 'success' : 'inProgress',
            },
            ...(researchingTask ? [researchingTask] : []),
          ];
      return (
        <div data-hook="ricos-widget" data-state="streaming">
          <MessageTimeline
            title={t('Widget_Title_Editing')}
            subtitle={
              hasContentStarted
                ? t('Widget_Subtitle_ImplementingChanges')
                : t('Widget_Subtitle_ExecutingPrompt')
            }
            tasks={[...initialTasks, ...tasksWithStatus]}
            footer={
              <div data-hook="ricos-widget-stop-button">
                <StopButton onCancel={onCancel} t={t} />
              </div>
            }
            t={t}
          />
        </div>
      );
    }
    case 'preview':
    case 'closed': {
      const researchingTask = buildResearchingTask(textMessages, 'success', t);
      const tasksWithStatus: CodegenTask[] = [
        {
          ...baseTasks[0],
          status: 'success',
        },
        ...(researchingTask ? [researchingTask] : []),
        {
          ...baseTasks[1],
          status: 'success',
        },
        {
          ...baseTasks[2],
          status: 'success',
          description: summaryMessage?.text ? [summaryMessage.text] : undefined,
        },
      ];

      return (
        <div data-hook="ricos-widget" data-state={aiState.state.type}>
          <MessageTimeline
            title={t('Widget_Title_Editing')}
            subtitle={t('Widget_Subtitle_Completed')}
            tasks={[...initialTasks, ...tasksWithStatus]}
            t={t}
          />
        </div>
      );
    }
    case 'error':
      return (
        <div
          data-hook="ricos-widget"
          data-state="error"
          data-error-code={aiState.state.error.applicationErrorCode}
        >
          <MessageTimeline
            title={t('Widget_Title_Editing')}
            subtitle={t('Widget_Subtitle_Error')}
            tasks={[
              ...initialTasks,
              {
                message: aiState.state.error.message,
                status: 'error',
                applicationErrorCode: aiState.state.error.applicationErrorCode,
                description: [aiState.state.error.message],
              },
            ]}
            onRetry={props.onRetry}
            t={t}
          />
        </div>
      );
    default:
      return (
        <div data-hook="ricos-widget" data-state="unknown">
          {t('Widget_Message_UnknownState')}
        </div>
      );
  }
};
