import {
  Box,
  Button,
  Collapse,
  Loader,
  SkeletonGroup,
  SkeletonLine,
  Text,
} from '@wix/design-system';
import {
  ChevronDown,
  CircleSmallFilledSmall,
  Confirm,
  StatusAlertSmall,
} from '@wix/wix-ui-icons-common/lazy';
import cs from 'classnames';
import React, { useEffect, useState } from 'react';

import { unreachable } from './../../_shared/uncreachable.js';

import { getAssistantErrorDescriptor } from './assistant-error-descriptor.js';
import styles from './assistant-timeline-scss.js';

const MAX_DESCRIPTION_LENGTH = 60;

const ExpandableText: React.FC<{
  text: string;
  className?: string;
}> = ({ text, className }) => {
  const [expanded, setExpanded] = useState(false);
  const needsTruncation = text.length > MAX_DESCRIPTION_LENGTH;
  const displayText =
    !expanded && needsTruncation ? text.slice(0, MAX_DESCRIPTION_LENGTH).trimEnd() + '…' : text;

  return (
    <Text
      className={className}
      variant="normal"
      size="small"
      onClick={needsTruncation ? () => setExpanded(prev => !prev) : undefined}
      style={needsTruncation ? { cursor: 'pointer' } : undefined}
    >
      {displayText}
    </Text>
  );
};

export type CodegenTask = {
  id?: string;
  message: string;
  description?: string[];
  isToolDescription?: boolean;
  status: 'inProgress' | 'success' | 'error' | 'pending';
  applicationErrorCode?: string;
};

export type MessageTimelineProps = {
  title: string;
  subtitle: string;
  tasks?: CodegenTask[];
  isLoading?: boolean;
  onRetry?: () => void;
  footer?: React.ReactNode;
  t: (key: string) => string;
};

const renderStepIcon = (status: CodegenTask['status']) => {
  switch (status) {
    case 'success':
      return <Confirm className={styles.stepIcon} />;
    case 'inProgress':
      return (
        <div className={styles.loaderContainer}>
          <Loader size="tiny" />
        </div>
      );
    case 'error':
      return <StatusAlertSmall className={styles.stepIcon} />;
    case 'pending':
      return <CircleSmallFilledSmall className={styles.stepIcon} />;
    default:
      throw unreachable(status);
  }
};

const getTimelineStepId = (task: CodegenTask, index: number) =>
  task.id ?? `step-${index}-${task.message}`;

export const MessageTimeline: React.FC<MessageTimelineProps> = ({
  title,
  subtitle,
  tasks,
  isLoading = false,
  onRetry,
  footer,
  t,
}) => {
  const visibleSteps = tasks ?? [];
  const expandedStepsResetKey = visibleSteps
    .map((task, index) => `${getTimelineStepId(task, index)}:${task.status}`)
    .join('|');

  const [expandedSteps, setExpandedSteps] = useState<Record<string, boolean>>({});

  useEffect(() => {
    const expanded: Record<string, boolean> = {};
    visibleSteps.forEach((task, index) => {
      expanded[getTimelineStepId(task, index)] = task.status === 'inProgress';
    });
    setExpandedSteps(expanded);
  }, [expandedStepsResetKey]);

  const toggleStep = (stepId: string) => {
    setExpandedSteps(prev => ({
      ...prev,
      [stepId]: !prev[stepId],
    }));
  };

  if (visibleSteps.some(step => step.status === 'error')) {
    const errorStep = visibleSteps.find(step => step.status === 'error');
    const errorDescriptor = getAssistantErrorDescriptor({
      applicationErrorCode: errorStep?.applicationErrorCode,
      message: errorStep?.description?.[0] ?? errorStep?.message,
      t,
    });

    return (
      <Box className={styles.assistantTimelineErrorContainer} direction="vertical">
        <Box verticalAlign="middle" marginBottom="8px">
          <Box marginRight="8px" color="#D6453D">
            <StatusAlertSmall size="24" />
          </Box>
          <Text size="small" weight="bold">
            {errorDescriptor.title}
          </Text>
        </Box>
        <Box marginBottom="16px">
          <Text size="small">{errorDescriptor.subtitle}</Text>
        </Box>
        {onRetry && errorDescriptor.isRetriable && (
          <div>
            <Button size="small" priority="primary" onClick={onRetry} skin="dark">
              {t('AssistantTimeline_Button_TryAgain')}
            </Button>
          </div>
        )}
      </Box>
    );
  }

  return (
    <Box className={styles.assistantTimelineContainer} direction="vertical">
      <Text variant="normal" size="small" weight="bold">
        {title}
      </Text>
      <Text className={styles.timelineSubtitle} variant="normal" size="small">
        {subtitle}
      </Text>
      <Box className={styles.stepsContainer} direction="vertical">
        {isLoading ? (
          <>
            <SkeletonGroup>
              <SkeletonLine width="75%" marginBottom="8px" />
              <SkeletonLine width="60%" marginBottom="16px" />
            </SkeletonGroup>
            <SkeletonGroup>
              <SkeletonLine width="80%" marginBottom="8px" />
              <SkeletonLine width="55%" marginBottom="16px" />
            </SkeletonGroup>
          </>
        ) : (
          visibleSteps.map((step, index) => {
            const stepId = getTimelineStepId(step, index);

            return (
              <Box
                key={stepId}
                className={cs(styles.stepItem, {
                  [styles.stepItemLoading]: step.status === 'inProgress',
                })}
                direction="vertical"
              >
                <div
                  onClick={() => toggleStep(stepId)}
                  onKeyDown={e => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      toggleStep(stepId);
                    }
                  }}
                  role="button"
                  tabIndex={0}
                >
                  <Box className={styles.stepHeader}>
                    {renderStepIcon(step.status)}
                    <Text className={styles.stepTitle} variant="normal" size="small">
                      {step.message}
                    </Text>
                    <ChevronDown
                      visibility={
                        step.description && step.description.length > 0 ? 'visible' : 'hidden'
                      }
                      className={`${styles.chevronIcon} ${
                        expandedSteps[stepId] ? styles.expanded : ''
                      }`}
                    />
                  </Box>
                </div>
                <Collapse open={!!expandedSteps[stepId]}>
                  <Box direction="vertical" className={styles.stepDetails}>
                    {step.description?.map((desc, descriptionIndex) => (
                      <ExpandableText
                        key={descriptionIndex}
                        text={desc}
                        className={cs(
                          styles.timelineSubtitle,
                          step.isToolDescription && styles.toolDescription
                        )}
                      />
                    ))}
                  </Box>
                </Collapse>
              </Box>
            );
          })
        )}
      </Box>
      {footer && <div className={styles.timelineFooter}>{footer}</div>}
    </Box>
  );
};
