import classNames from 'classnames';
import type { FunctionComponent, InputHTMLAttributes, KeyboardEvent } from 'react';
import React, { useEffect, useState } from 'react';

import {
  ACTION_COLOR_LIVESITE,
  BG_COLOR_LIVESITE,
  SLIDER_THUMB_VISIBILITY,
  SLIDER_TRACK_SIZE,
} from '../consts.js';
import styles from '../statics/styles/slider-scss.js';

type ThumbVisibilityKeys = keyof typeof SLIDER_THUMB_VISIBILITY;
type TrackSizeKeys = keyof typeof SLIDER_TRACK_SIZE;

interface SliderProps {
  value: number;
  min?: number;
  max?: number;
  onChange: (value: number) => void;
  onChangeCommitted?: (value: number) => void;
  dataHook?: string;
  step?: string;
  thumbVisibility?: (typeof SLIDER_THUMB_VISIBILITY)[ThumbVisibilityKeys];
  trackSize?: (typeof SLIDER_TRACK_SIZE)[TrackSizeKeys];
  tabIndex?: number;
  ariaProps?: InputHTMLAttributes<HTMLInputElement>;
  languageDir: string;
  ariaLabel?: string;
  disabled?: boolean;
  className?: string;
}

export const Slider: FunctionComponent<SliderProps> = ({
  min = 0,
  max = 10,
  tabIndex = 0,
  onChange,
  dataHook,
  ariaProps,
  value,
  onChangeCommitted,
  languageDir,
  thumbVisibility = SLIDER_THUMB_VISIBILITY.fixed,
  trackSize = SLIDER_TRACK_SIZE.medium,
  step,
  ariaLabel,
  disabled,
  className,
}) => {
  const [fillPercentage, setFillPercentage] = useState(0);
  const track = {
    fill: ACTION_COLOR_LIVESITE,
    unFilled: BG_COLOR_LIVESITE,
    gradientDeg: languageDir === 'rtl' ? '270deg' : '90deg',
  };
  const bgStyle = {
    background: `linear-gradient(${track.gradientDeg} ,${track.fill} ${fillPercentage}%, ${
      track.unFilled
    } ${fillPercentage + 0.1}%)`,
  };

  const isFixedThumb = thumbVisibility === SLIDER_THUMB_VISIBILITY.fixed;

  const onKeyUp = (event: KeyboardEvent) => {
    switch (event.key) {
      case 'ArrowUp':
      case 'ArrowDown':
      case 'ArrowRight':
      case 'ArrowLeft':
      case 'Home':
      case 'End':
      case 'PageUp':
      case 'PageDown':
        onChangeCommitted?.((event.target as HTMLInputElement).valueAsNumber);
        break;
      default:
        return;
    }
  };

  const onKeyDown = (e: $TSFixMe) => {
    switch (e.key) {
      case 'ArrowUp':
      case 'ArrowDown':
      case 'ArrowRight':
      case 'ArrowLeft':
      case 'Home':
      case 'End':
      case 'PageUp':
      case 'PageDown':
        onChange?.(e.target.valueAsNumber);
        break;
      default:
        return;
    }
  };

  useEffect(() => {
    setFillPercentage((100 * (value - min)) / (max - min));
  }, [value]);

  return (
    <input
      {...ariaProps}
      aria-label={ariaLabel}
      tabIndex={tabIndex}
      type={'range'}
      className={classNames(styles.slider, styles.wrapperSlider, styles[trackSize], className, {
        [styles.slider_fixed_thumb]: isFixedThumb,
      })}
      data-hook={dataHook}
      onChange={e => onChange(e.target.valueAsNumber)}
      value={value}
      min={min}
      max={max}
      step={step}
      onMouseUp={e => onChangeCommitted?.((e.target as HTMLInputElement).valueAsNumber)}
      onTouchEnd={e => onChangeCommitted?.((e.target as HTMLInputElement).valueAsNumber)}
      onKeyUp={onKeyUp}
      onKeyDown={onKeyDown}
      style={bgStyle}
      disabled={disabled}
    />
  );
};
